// ABOUTME: Property tests for grading scales, generated by a seeded fast-check run so a failure
// ABOUTME: reproduces: every score in a contiguous scale matches exactly one band, boundaries go
// ABOUTME: to the band the declared convention names, raising a score never moves backwards
// ABOUTME: through the declared order, and every trace replays into its own band.

import * as fc from 'fast-check';
import { describe, expect, it } from 'vitest';

import { compareExact, parseExact, type Exact } from '../../engine';
import { givenScore, lookupScaleBand, prepareGradingScale, replayScaleLookup } from '../index';
import type { GradingScaleDefinition, PreparedGradingScale, ScaleLookup } from '../index';

const OPTIONS = { seed: 20261021, numRuns: 200 } as const;

function exactOf(text: string): Exact {
  const value = parseExact(text);
  if (value === null) throw new Error(`not an exact value: ${text}`);
  return value;
}

/** `value` written with `scale` decimal places, without touching floating point arithmetic. */
function decimalAt(value: number, scale: number): string {
  const sign = value < 0 ? '-' : '';
  const digits = String(Math.abs(value)).padStart(scale + 1, '0');
  const split = digits.length - scale;
  return scale === 0 ? `${sign}${digits}` : `${sign}${digits.slice(0, split)}.${digits.slice(split)}`;
}

/**
 * Cut points between bands: 0 and 100 always appear, so every generated scale covers its domain
 * from zero to a hundred and only the cuts in between vary.
 */
const cutsArbitrary: fc.Arbitrary<readonly number[]> = fc
  .uniqueArray(fc.integer({ min: 0, max: 100 }), { minLength: 1, maxLength: 6 })
  .map((values) => [...new Set([0, ...values, 100])].sort((left, right) => left - right));

/**
 * A generated scale over the cuts.
 *
 * Under the exclusive convention the bands tile the cuts exactly: `[cut, next)`.
 * Under the inclusive convention a band runs to the mark before the next cut, except the last
 * band, which runs to 100: `[cut, next - 1]` and `[last, 100]`.
 */
function definitionOf(
  cuts: readonly number[],
  reversed: boolean,
  inclusive: boolean
): GradingScaleDefinition {
  const last = cuts.length - 1;
  const bands = cuts.slice(0, -1).map((min, index) => {
    const max = inclusive ? (index === last - 1 ? cuts[index + 1] : cuts[index + 1] - 1) : cuts[index + 1];
    return { code: `B${index}`, label: `Band ${index}`, min, max, points: index + 1 };
  });
  return {
    code: `generated_${inclusive ? 'inclusive' : 'exclusive'}_${reversed ? 'reversed' : 'declared'}`,
    kind: 'numeric_bands',
    input: 'percent',
    ...(inclusive ? { upper: 'inclusive' as const } : {}),
    bands: reversed ? [...bands].reverse() : bands,
  };
}

function preparedOf(definition: GradingScaleDefinition): PreparedGradingScale {
  const preparation = prepareGradingScale(definition);
  if (!preparation.ok) {
    throw new Error(
      `expected a valid generated scale, got ${preparation.issues.map((issue) => issue.code).join(', ')}`
    );
  }
  return preparation.scale;
}

/** `n` as a sampled score: hundredths for exclusive bands, whole marks for inclusive bands. */
function scoreText(inclusive: boolean, n: number): string {
  return inclusive ? String(Math.min(100, Math.floor(n / 100))) : decimalAt(n, 2);
}

function lookupAt(scale: PreparedGradingScale, text: string): ScaleLookup {
  return lookupScaleBand(scale, givenScore(exactOf(text)));
}

function matchedCheck(lookup: ScaleLookup): { readonly index: number; readonly min: string; readonly max: string } {
  const check = lookup.trace.checks.find((candidate) => candidate.matched);
  if (check === undefined) throw new Error(`no band matched ${lookup.trace.score}`);
  return check;
}

describe('every score in a contiguous scale maps to exactly one band', () => {
  it('does so over exclusive bands', () => {
    fc.assert(
      fc.property(cutsArbitrary, fc.boolean(), fc.integer({ min: 0, max: 9999 }), (cuts, reversed, n) => {
        const scale = preparedOf(definitionOf(cuts, reversed, false));
        const lookup = lookupAt(scale, decimalAt(n, 2));

        expect(lookup.matched).toBe(true);
        expect(lookup.trace.checks.filter((check) => check.matched)).toHaveLength(1);
        if (!lookup.matched) throw new Error('expected a match');
        expect(lookup.band.code).toBe(lookup.trace.band);
        expect(matchedCheck(lookup).index).toBeGreaterThanOrEqual(0);
      }),
      OPTIONS
    );
  });

  it('does so over inclusive bands with whole-mark scores', () => {
    fc.assert(
      fc.property(cutsArbitrary, fc.boolean(), fc.integer({ min: 0, max: 10000 }), (cuts, reversed, n) => {
        const scale = preparedOf(definitionOf(cuts, reversed, true));
        const lookup = lookupAt(scale, scoreText(true, n));

        expect(lookup.matched).toBe(true);
        expect(lookup.trace.checks.filter((check) => check.matched)).toHaveLength(1);
        if (!lookup.matched) throw new Error('expected a match');
        expect(lookup.band.code).toBe(lookup.trace.band);
      }),
      OPTIONS
    );
  });

  it('never lets two bands claim the same score', () => {
    fc.assert(
      fc.property(cutsArbitrary, fc.boolean(), fc.boolean(), fc.integer({ min: 0, max: 9999 }), (cuts, reversed, inclusive, n) => {
        const scale = preparedOf(definitionOf(cuts, reversed, inclusive));
        const lookup = lookupAt(scale, scoreText(inclusive, n));
        expect(lookup.trace.checks.filter((check) => check.matched).length).toBeLessThanOrEqual(1);
      }),
      OPTIONS
    );
  });
});

describe('shared boundaries belong to one band', () => {
  it('sends an exclusive boundary up to the band that starts there', () => {
    fc.assert(
      fc.property(cutsArbitrary, fc.boolean(), (cuts, reversed) => {
        const scale = preparedOf(definitionOf(cuts, reversed, false));
        for (const cut of cuts.slice(1, -1)) {
          expect(matchedCheck(lookupAt(scale, String(cut))).min).toBe(String(cut));
          const below = lookupAt(scale, decimalAt(cut * 100 - 1, 2));
          expect(compareExact(exactOf(matchedCheck(below).max), exactOf(String(cut)))).toBe(0);
        }
      }),
      OPTIONS
    );
  });

  it('keeps an inclusive boundary in the lower band and starts the next at the following mark', () => {
    fc.assert(
      fc.property(cutsArbitrary, fc.boolean(), (cuts, reversed) => {
        const scale = preparedOf(definitionOf(cuts, reversed, true));
        for (const cut of cuts.slice(1, -1)) {
          expect(matchedCheck(lookupAt(scale, String(cut - 1))).max).toBe(String(cut - 1));
          expect(matchedCheck(lookupAt(scale, String(cut))).min).toBe(String(cut));
        }
        expect(matchedCheck(lookupAt(scale, '100')).max).toBe('100');
      }),
      OPTIONS
    );
  });
});

describe('raising a score never moves backwards through the declared order', () => {
  it('keeps the band index monotonic in the direction the scale declares', () => {
    fc.assert(
      fc.property(
        cutsArbitrary,
        fc.boolean(),
        fc.boolean(),
        fc.integer({ min: 0, max: 9999 }),
        fc.integer({ min: 0, max: 9999 }),
        (cuts, reversed, inclusive, left, right) => {
          const scale = preparedOf(definitionOf(cuts, reversed, inclusive));
          if (!reversed) expect(scale.direction).toBe('ascending');
          else if (scale.bands.length > 1) expect(scale.direction).toBe('descending');

          const low = scoreText(inclusive, Math.min(left, right));
          const high = scoreText(inclusive, Math.max(left, right));
          expect(compareExact(exactOf(low), exactOf(high))).toBeLessThanOrEqual(0);

          const lowIndex = matchedCheck(lookupAt(scale, low)).index;
          const highIndex = matchedCheck(lookupAt(scale, high)).index;

          if (scale.direction === 'ascending') expect(lowIndex).toBeLessThanOrEqual(highIndex);
          else expect(lowIndex).toBeGreaterThanOrEqual(highIndex);
        }
      ),
      OPTIONS
    );
  });
});

describe('the trace replays into the band it recorded', () => {
  it('recomputes the match and boundary from the checks alone', () => {
    fc.assert(
      fc.property(
        cutsArbitrary,
        fc.boolean(),
        fc.boolean(),
        fc.integer({ min: 0, max: 9999 }),
        (cuts, reversed, inclusive, n) => {
          const scale = preparedOf(definitionOf(cuts, reversed, inclusive));
          const lookup = lookupAt(scale, scoreText(inclusive, n));
          const replayed = replayScaleLookup(lookup.trace);

          expect(replayed.band).toBe(lookup.band === null ? null : lookup.band.code);
          expect(replayed.boundary).toBe(lookup.trace.boundary);
          expect(replayed.band).toBe(lookup.trace.band);
        }
      ),
      OPTIONS
    );
  });
});
